use verus::prelude::*;

verus! {
    /// Given a non‐empty vector `a` of 32‐bit signed integers,
    /// return a new vector formed by dropping the first element of `a`.
    /// The result has length exactly one less than `a`, preserves the
    /// relative order of the remaining elements, and does not mutate `a`.
    pub fn remove_front(a: &Vec<i32>) -> Vec<i32>
        requires
            // precondition: input is non‐empty
            a.len() > 0,
        ensures
            // the result has length one less than `a`
            result.len() == a.len() - 1,
        ensures
            // for each valid index i in result, result[i] == a[i+1]
            forall(|i: usize| i < result.len() ==> result[i] == a[i + 1]),
        ensures
            // `a` remains unchanged
            a@ == old(a@),
    {
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 1;

        // We loop from i=1 up to a.len(), pushing a[i] each iteration.
        // At iteration entry:
        //   - 1 <= i <= a.len()
        //   - res.len() == i - 1
        //   - res[j] == a[j+1]  for all j < res.len()
        // The loop terminates when i == a.len(), so we have pushed
        // exactly a.len()-1 elements.
        while i < a.len()
            invariant 1 <= i && i <= a.len()
            invariant res.len() == i - 1
            invariant forall(|j: usize| j < res.len() ==> res[j] == a[j + 1])
            decreases a.len() - i
        {
            res.push(a[i]);
            i += 1;
        }

        res
    }
}